const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const s = lines[0].trim();
const n = s.length;
let rank = Array.from(s, c => c.charCodeAt(0));
const sa = Array.from({ length: n }, (_, i) => i).sort((a, b) => rank[a] - rank[b]);
for (let k = 1; k < n; k *= 2) {
  const second = (i) => (i + k < n ? rank[i + k] : -1);
  sa.sort((a, b) => rank[a] - rank[b] || second(a) - second(b));
  const tmp = new Array(n).fill(0);
  for (let idx = 1; idx < n; idx++) {
    const a = sa[idx - 1], b = sa[idx];
    tmp[b] = tmp[a] + (rank[a] !== rank[b] || second(a) !== second(b) ? 1 : 0);
  }
  rank = tmp;
  if (rank[sa[n - 1]] === n - 1) break;
}
const rk = new Array(n).fill(0);
for (let idx = 0; idx < n; idx++) rk[sa[idx]] = idx;
let total = n * (n + 1) / 2, h = 0;
for (let i = 0; i < n; i++) {
  if (rk[i] > 0) {
    const j = sa[rk[i] - 1];
    while (i + h < n && j + h < n && s[i + h] === s[j + h]) h++;
    total -= h;
    if (h > 0) h--;
  } else h = 0;
}
console.log(String(total));

