import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();
        int n = s.length();
        Integer[] sa = new Integer[n];
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) { sa[i] = i; rank[i] = s.charAt(i); }
        for (int k = 1; k < n; k *= 2) {
            final int kk = k;
            final int[] r = rank;
            Comparator<Integer> cmp = (a, b) -> {
                if (r[a] != r[b]) return Integer.compare(r[a], r[b]);
                int ra = a + kk < n ? r[a + kk] : -1, rb = b + kk < n ? r[b + kk] : -1;
                return Integer.compare(ra, rb);
            };
            Arrays.sort(sa, cmp);
            int[] tmp = new int[n];
            for (int idx = 1; idx < n; idx++) tmp[sa[idx]] = tmp[sa[idx - 1]] + (cmp.compare(sa[idx - 1], sa[idx]) != 0 ? 1 : 0);
            rank = tmp;
            if (rank[sa[n - 1]] == n - 1) break;
        }
        int[] rk = new int[n];
        for (int idx = 0; idx < n; idx++) rk[sa[idx]] = idx;
        long total = (long) n * (n + 1) / 2;
        int h = 0;
        for (int i = 0; i < n; i++) {
            if (rk[i] > 0) {
                int j = sa[rk[i] - 1];
                while (i + h < n && j + h < n && s.charAt(i + h) == s.charAt(j + h)) h++;
                total -= h;
                if (h > 0) h--;
            } else h = 0;
        }
        System.out.println(total);
    }
}

