#include <bits/stdc++.h>
using namespace std;
int main() {
    string s;
    cin >> s;
    int n = s.size();
    vector<int> sa(n), rank_(n), tmp(n);
    iota(sa.begin(), sa.end(), 0);
    for (int i = 0; i < n; i++) rank_[i] = s[i];
    for (int k = 1; k < n; k *= 2) {
        auto key = [&](int i) { return make_pair(rank_[i], i + k < n ? rank_[i + k] : -1); };
        sort(sa.begin(), sa.end(), [&](int a, int b) { return key(a) < key(b); });
        tmp[sa[0]] = 0;
        for (int idx = 1; idx < n; idx++) tmp[sa[idx]] = tmp[sa[idx - 1]] + (key(sa[idx - 1]) < key(sa[idx]) ? 1 : 0);
        rank_ = tmp;
        if (rank_[sa[n - 1]] == n - 1) break;
    }
    vector<int> rk(n);
    for (int idx = 0; idx < n; idx++) rk[sa[idx]] = idx;
    long long total = (long long)n * (n + 1) / 2;
    int h = 0;
    for (int i = 0; i < n; i++) {
        if (rk[i] > 0) {
            int j = sa[rk[i] - 1];
            while (i + h < n && j + h < n && s[i + h] == s[j + h]) h++;
            total -= h;
            if (h > 0) h--;
        } else h = 0;
    }
    printf("%lld\n", total);
    return 0;
}
